// Records completed Paytrail payments into Supabase payments_paytrail, running in a
// parallel branch off "Code in JavaScript1" -- does not touch or depend on the existing
// offer-fulfillment branches (PDF receipts, emails, order creation). continueOnFail is set
// on every node in this branch so a bug here can never break those for a real customer.
// Added 2026-08-12 -- see docs/STATUS.md workstream E.
const crypto = require('crypto');

const AIRTABLE_API_KEY = 'AIRTABLE_API_KEY_PLACEHOLDER';
const AIRTABLE_BASE_ID = 'appGkn53DdtjFGmWV';
const AIRTABLE_OFFERS_TABLE = 'Offers';
const PAYTRAIL_MERCHANT_ID = 'PAYTRAIL_MERCHANT_ID_PLACEHOLDER';
const PAYTRAIL_SECRET_KEY = 'PAYTRAIL_SECRET_KEY_PLACEHOLDER';

const q = $json.query || {};
const transactionId = q['checkout-transaction-id'];
const reference = q['checkout-reference'] || null;

if (!transactionId) {
  return [];
}

// -- 1. Resolve order_id ----------------------------------------------------
// checkout-reference is NOT reliably an orders.order_id -- confirmed live 2026-08-12 it's a
// UUID order_id for direct order-settlement payments, but a short Airtable OfferID for the
